    EXECUTE $q$DROP POLICY IF EXISTS room_bans_write_owner ON public.room_bans$q$;
    EXECUTE $q$CREATE POLICY room_bans_write_owner ON public.room_bans FOR INSERT TO authenticated
            WITH CHECK (banned_by = (SELECT app_auth.uid()) AND (SELECT app_auth.owns_room(room_bans.room_id)))$q$;
    EXECUTE $q$DROP POLICY IF EXISTS room_bans_update_owner ON public.room_bans$q$;
    EXECUTE $q$CREATE POLICY room_bans_update_owner ON public.room_bans FOR UPDATE TO authenticated
            USING ((SELECT app_auth.owns_room(room_bans.room_id)))
            WITH CHECK (banned_by = (SELECT app_auth.uid()) AND (SELECT app_auth.owns_room(room_bans.room_id)))$q$;
    EXECUTE $q$DROP POLICY IF EXISTS room_bans_delete_owner ON public.room_bans$q$;
    EXECUTE $q$CREATE POLICY room_bans_delete_owner ON public.room_bans FOR DELETE TO authenticated
            USING ((SELECT app_auth.owns_room(room_bans.room_id)))$q$;
    EXECUTE $q$DROP POLICY IF EXISTS room_activity_select_member ON public.room_activity$q$;
    EXECUTE $q$CREATE POLICY room_activity_select_member ON public.room_activity FOR SELECT TO authenticated
            USING ((SELECT app_auth.is_room_member(room_activity.room_id)))$q$;
    EXECUTE $q$DROP POLICY IF EXISTS room_activity_insert_member ON public.room_activity$q$;
    EXECUTE $q$CREATE POLICY room_activity_insert_member ON public.room_activity FOR INSERT TO authenticated
            WITH CHECK (user_id = (SELECT app_auth.uid()) AND (SELECT app_auth.is_room_member(room_activity.room_id)))$q$;
    EXECUTE $q$DROP POLICY IF EXISTS room_summaries_select_member ON public.room_summaries$q$;
    EXECUTE $q$CREATE POLICY room_summaries_select_member ON public.room_summaries FOR SELECT TO authenticated
            USING ((SELECT app_auth.is_room_member(room_summaries.room_id)))$q$;
    EXECUTE $q$DROP POLICY IF EXISTS room_reactions_select_member ON public.room_reactions$q$;
    EXECUTE $q$CREATE POLICY room_reactions_select_member ON public.room_reactions FOR SELECT TO authenticated
            USING (EXISTS (SELECT 1 FROM public.room_messages m WHERE m.id = room_reactions.message_id AND (SELECT app_auth.is_room_member(m.room_id))))$q$;
    EXECUTE $q$DROP POLICY IF EXISTS room_reactions_insert_self ON public.room_reactions$q$;
    EXECUTE $q$CREATE POLICY room_reactions_insert_self ON public.room_reactions FOR INSERT TO authenticated
            WITH CHECK (user_id = (SELECT app_auth.uid()) AND EXISTS (SELECT 1 FROM public.room_messages m WHERE m.id = room_reactions.message_id AND (SELECT app_auth.is_room_member(m.room_id))))$q$;
    EXECUTE $q$DROP POLICY IF EXISTS room_reactions_delete_self ON public.room_reactions$q$;
    EXECUTE $q$CREATE POLICY room_reactions_delete_self ON public.room_reactions FOR DELETE TO authenticated
            USING (user_id = (SELECT app_auth.uid()))$q$;
    EXECUTE $q$DROP POLICY IF EXISTS offering_concept_stats_select_enrolled ON public.offering_concept_stats$q$;
    EXECUTE $q$CREATE POLICY offering_concept_stats_select_enrolled ON public.offering_concept_stats FOR SELECT TO authenticated
