            USING ((SELECT app_auth.uid()) IS NOT NULL AND (visibility = 'shared' OR uploader_id = (SELECT app_auth.uid()) OR EXISTS (SELECT 1 FROM public.course_chunk_contributors k WHERE k.chunk_id = course_chunks.id AND k.user_id = (SELECT app_auth.uid()))))$q$;
    EXECUTE $q$DROP POLICY IF EXISTS course_chunk_contributors_select_own ON public.course_chunk_contributors$q$;
